/**
 * The v0.2 scenario catalogue as data: one row per
 * decision the firewall must get right, with the session state, the tool call
 * as Claude Code sends it, and the expected decision and rule.
 *
 * Placeholders only, never payload text: {WS} workspace, {H} home, {O} a
 * sibling folder outside the workspace, {TMP} scratch, {FW_PKG} the installed
 * firewall package. Data tokens ({PAN}, {AWS_KEY}, {SEEN}, ...) are synthetic
 * values generated by the runner (src/catalogue.ts) so that the detectors fire;
 * none is a real credential or a real person's data.
 *
 * `item` names the feature or gap tag that introduces or changes the row; the
 * suite runs such a row only once that feature is built and reports the rest
 * as todo.
 */

export type Category = "DEV" | "GIT" | "PKG" | "DOC" | "MCP" | "MEM" | "CRED" | "UNAT" | "MULTI" | "INC" | "SELF" | "INST";

/** T trusted · U untrusted · U+S untrusted and sensitive · UA-T / UA-U unattended. */
export type RowState = "T" | "U" | "U+S" | "UA-T" | "UA-U";

export type Expectation = "allow" | "allow+taint" | "allow+S" | "allow+taint+S" | "ask" | "queue" | "deny";

export interface CatStep {
  tool: string;
  input: Record<string, unknown>;
  /** The tool's output, for the PostToolUse event (a neutral placeholder by default). */
  post?: unknown;
  /** Claude Code's mcp_server.source for an MCP tool (default "user": a server the person configured). */
  mcpSource?: string;
  /** The session this step runs in (default "main"); a different name is a new session. */
  session?: string;
  /** The working directory of the step (default {WS}). */
  cwd?: string;
  /** Files the tool would write when it runs (for Bash steps; Write/Edit are applied automatically). */
  apply?: Record<string, string>;
  /** Judge this step (a setup step otherwise). */
  expect?: Expectation;
  rule?: string;
}

export interface CatalogueRow {
  id: string;
  category: Category;
  task: string;
  states: RowState[];
  /** Steps in order; the last one is judged with the row's expectation unless a step carries its own. */
  steps: CatStep[];
  expect: Expectation;
  /** A rule id expected among the decision's rules ("A|B" means either). */
  rule?: string;
  /** The feature or gap tag that introduces or changes this row. */
  item?: string;
  /** A prompt the person typed first (UserPromptSubmit). */
  prompt?: string;
  /** The user's policy file (the current schema version is added). */
  policy?: Record<string, unknown>;
  /** A project policy file (.launchsafe-firewall.json). */
  projectPolicy?: Record<string, unknown>;
  /** Files present before the row (relative to nothing: use placeholders). */
  files?: Record<string, string>;
  /** Install the firewall's hooks into {H}/.claude/settings.json first. */
  installed?: boolean;
  /** Then install the sandbox profile into {H}/.claude/settings.json the way doctor --fix does (planned from the default policy and recorded). */
  sandboxProfile?: boolean;
  /** Not automated, with the reason (out of scope, needs a terminal, covered elsewhere). */
  skip?: string;
  note?: string;
  /** Where this row's expectation differs from the first-draft catalogue, and why. */
  deviation?: string;
  /**
   * The agent whose hook sends the events (default Claude Code). Steps name that agent's native
   * tools; the setup steps (taint, private data) are translated by src/agent-replay.ts. "ask" is
   * expected as "queue" for an agent whose hooks cannot ask.
   */
  agent?: "claude" | "codex" | "gemini";
}

// --- builders ---------------------------------------------------------------------------------------

const B = (command: string, extra: Partial<CatStep> = {}): CatStep => ({ tool: "Bash", input: { command }, ...extra });
const T = (tool: string, input: Record<string, unknown> = {}, extra: Partial<CatStep> = {}): CatStep => ({ tool, input, ...extra });
const R = (file_path: string): CatStep => T("Read", { file_path });
const W = (file_path: string, content = "x\n"): CatStep => T("Write", { file_path, content });
const E = (file_path: string, old_string: string, new_string: string): CatStep => T("Edit", { file_path, old_string, new_string });
const M = (name: string, input: Record<string, unknown> = {}, extra: Partial<CatStep> = {}): CatStep => T(`mcp__${name}`, input, extra);
const WF = (url: string): CatStep => T("WebFetch", { url, prompt: "summarize" });
/** n setup steps (the earlier calls a budget counts). */
const repeat = (n: number, step: (i: number) => CatStep): CatStep[] => Array.from({ length: n }, (_, i) => step(i));

type Opts = Partial<Omit<CatalogueRow, "id" | "category" | "task" | "states" | "steps" | "expect">>;

function row(id: string, task: string, states: RowState[], steps: CatStep | CatStep[], expect: Expectation, rule?: string, o: Opts = {}): CatalogueRow {
  const category = id.split("-")[0] as Category;
  return { id, category, task, states, steps: Array.isArray(steps) ? steps : [steps], expect, ...(rule !== undefined ? { rule } : {}), ...o };
}

